INSERT INTO `system_mail_templates` VALUES (1,'rainlab.user::mail.activate',NULL,'Activate a new user',NULL,NULL,1,0,'2019-02-19 18:24:45','2019-02-19 18:24:45'),(2,'rainlab.user::mail.welcome',NULL,'User confirmed their account',NULL,NULL,1,0,'2019-02-19 18:24:45','2019-02-19 18:24:45'),(3,'rainlab.user::mail.restore',NULL,'User requests a password reset',NULL,NULL,1,0,'2019-02-19 18:24:45','2019-02-19 18:24:45'),(4,'rainlab.user::mail.new_user',NULL,'Notify admins of a new sign up',NULL,NULL,2,0,'2019-02-19 18:24:45','2019-02-19 18:24:45'),(5,'rainlab.user::mail.reactivate',NULL,'User has reactivated their account',NULL,NULL,1,0,'2019-02-19 18:24:45','2019-02-19 18:24:45'),(6,'rainlab.user::mail.invite',NULL,'Invite a new user to the website',NULL,NULL,1,0,'2019-02-19 18:24:45','2019-02-19 18:24:45'),(7,'backend::mail.invite',NULL,'Invite new admin to the site',NULL,NULL,2,0,'2019-02-19 18:24:45','2019-02-19 18:24:45'),(8,'backend::mail.restore',NULL,'Reset an admin password',NULL,NULL,2,0,'2019-02-19 18:24:45','2019-02-19 18:24:45'),(9,'BT.sales.newquote','BT New Quote','BT New Quote','Dear {{ name }},\r\n\r\nThank you for giving us the opportunity to present you with a quotation.\r\n\r\nKindly note the attached quote created for {{company_name}}. Quote reference is {{ref}}. Please sign and return the quote to {{response_quote}}\r\n\r\n{{notes}}\r\n\r\nRegards,\r\n\r\nBT Industrial Team','',1,1,'2019-02-19 18:31:54','2019-08-14 08:46:51'),(10,'BT.sales.response.discount','Request: Quote Discount {{ref}}','Request: Quote Discount {{ref}}','Hi {{ to_name }},\r\n\r\n{{sales_name}} is requesting a quote discount. Here are the Details below:\r\n\r\n**Company Name:** {{company_name}}.\r\n\r\n**Quote Refence:** {{ref}}. \r\n\r\n**Quote Total:** R{{quote_total}}\r\n\r\n**Message:** {{notes}}\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2019-03-19 15:40:50','2019-06-13 13:38:33'),(11,'BT.sales.response.discountresponse','Notification: Quote Discount Approved {{ref}}','Notification: Quote Discount Approved {{ref}}','Hi {{ to_name }},\r\n\r\nA {{disc_perc}} has been given to the quote {{ref}} for {{company_name}}.\r\n\r\n\r\n**Message:** {{notes}}\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2019-03-20 22:42:09','2019-06-13 13:38:47'),(12,'BT.sales.response.requestdelivery','Request: Quote Delivery {{ref}}','Request: Quote Discount {{ref}}','Hi {{ to_name }},\r\n\r\n{{sales_name}} is requesting a price for delivery. Here are the Details below:\r\n\r\n**Company Name:** {{company_name}}.\r\n\r\n**Quote Refence:** {{ref}}. \r\n\r\n**Quote Total:** R{{quote_total}}\r\n\r\n**Delivery Address:** {{notes}}\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2019-04-22 09:18:57','2019-06-13 13:39:04'),(13,'bt.notify.daily','BailaERP Daily Notification','BailaERP Daily Notification','Hi {{ name }},\r\n\r\nNotification Date and Time: {{ \"now\"|date(\"m/d/Y H:i\") }} \r\n\r\nNew link to portal is : http://bailaerp.bt-industrial.co.za\r\n\r\n\r\n<h1>In Cage Material</h1>\r\n<table class=\"\" style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellspacing=\"0px\" cellpadding=\"2px\"  border=\"1\">\r\n<thead>\r\n	<tr>\r\n        <!-- <th>Date</th> -->\r\n        <th>Product Name</th>\r\n		<th>Supplier</th>\r\n		<th>Supplier Batch</th>\r\n		<th>Delivery Date</th>\r\n        <th align=\"right\">Price Per KG</th>\r\n        <th align=\"right\">Start Weight</th>\r\n        <th align=\"right\">Released</th>\r\n        <th align=\"right\">Auto In-Cage</th>\r\n        <th align=\"right\">In-Cage</th>\r\n        <th align=\"right\">Value</th>\r\n        <th align=\"right\">Used</th>\r\n	</tr>\r\n</thead>\r\n<tbody>\r\n    {% set total = 0 %}\r\n    {% set totalrelesed = 0 %}\r\n    {% set totalincage = 0 %}\r\n    {% set totalvalue = 0 %}\r\n    {% set totalused = 0 %}\r\n    {% set totalincage_shadrak = 0%}\r\n\r\n					{% for itemobject in tblincage %}					\r\n						{% set total_auto_rl = 0 %}\r\n						{% for rl in itemobject.release %}\r\n							{% set total_auto_rl = total_auto_rl + rl.kg %}\r\n						{% endfor %}	\r\n							{% set total_auto = (itemobject.weight - total_auto_rl) %}			\r\n			        	<tr class=\"{{(total_auto < 1)? \'text-danger\':\'\'}}\">\r\n							<!-- <td>{{itemobject.datecaptured|date(\"m/d/Y H:00\")}}</td> -->\r\n						<td>{{itemobject.productname.name}}</td>\r\n								<td>{{itemobject.productname.supplier.name}}</td>\r\n								<td>{{itemobject.supplier_batch}}</td>\r\n								<td>{{itemobject.date_of_receipt|date(\"m/d/Y\")}}</td>\r\n							<td align=\"right\">\r\n							R {{( itemobject.pricekg)|number_format(2, \'.\', \',\')}}\r\n							\r\n							</td>\r\n							<td align=\"right\">\r\n								{{itemobject.weight}}\r\n								{% set total = total+itemobject.weight %}\r\n							</td>\r\n\r\n							\r\n							<td align=\"right\">\r\n								{% set total_auto_rl = 0 %}\r\n								{% for rl in itemobject.release %}\r\n									{% set total_auto_rl = total_auto_rl + rl.kg %}\r\n								{% endfor %} \r\n								{{total_auto_rl}} kg\r\n								{% set totalrelesed = totalrelesed + total_auto_rl %}\r\n							</td>\r\n							<td align=\"right\">\r\n								{{itemobject.weight - total_auto_rl}} kg\r\n\r\n								{% set totalincage =  totalincage + (itemobject.weight - total_auto_rl)%}\r\n							</td>\r\n							<td align=\"right\">\r\n								{% set incagecount = 9999999999 %}\r\n\r\n								{% for rl in itemobject.incage %}\r\n									{% set incagecount = rl.kg %}\r\n								{% endfor %} \r\n\r\n								{% if incagecount == 9999999999 %}\r\n\r\n									<span class=\"text-info\" >\r\n									not available\r\n									</span>\r\n										{% set incagecount = 0 %}\r\n								{% else %}\r\n								\r\n										{% if (incagecount != (itemobject.weight - total_auto_rl)) %}\r\n											<span class=\"text-warning\" >\r\n												warning {{incagecount}} kg\r\n												/ {{(incagecount - (itemobject.weight - total_auto_rl))}} kg\r\n											</span>\r\n										{% else  %}\r\n											{{incagecount}} kg\r\n										{% endif %}\r\n									\r\n									\r\n								{% endif %}\r\n								{% set totalincage_shadrak =  totalincage_shadrak + incagecount %}\r\n							</td>\r\n							\r\n\r\n							<td align=\"right\">\r\n							R {{((itemobject.weight - total_auto_rl) * itemobject.pricekg)|number_format(2, \'.\', \',\')}}\r\n							{% set totalvalue = totalvalue + (itemobject.weight - total_auto_rl) * itemobject.pricekg %}\r\n							</td>\r\n\r\n							<td align=\"right\">\r\n								{% set total_auto_used = 0 %}\r\n								{% for rl in itemobject.used %}\r\n									{% set total_auto_used = total_auto_used + rl.kg %}\r\n								{% endfor %} \r\n								{{total_auto_used}} kg\r\n								{% set totalused = totalused + total_auto_used  %}\r\n							</td>\r\n					      	\r\n					      	\r\n					     </tr>\r\n					    \r\n					{% endfor %} \r\n				</tbody>\r\n				<tfoot>\r\n						<tr>\r\n							<td align=\"left\" colspan=\"5\"><b>TOTAL</b></td>\r\n							<td align=\"right\"><b>{{total|number_format(1, \'.\', \',\')}} KG</b></td>\r\n							<td align=\"right\"><b>{{totalrelesed|number_format(1, \'.\', \',\')}} KG</b></td>\r\n							<td align=\"right\"><b>{{totalincage|number_format(1, \'.\', \',\')}} KG</b></td>\r\n							<td align=\"right\"><b>{{totalincage_shadrak|number_format(1, \'.\', \',\')}} KG</b></td>\r\n							<td align=\"right\"><b>R {{(totalvalue)|number_format(2, \'.\', \',\')}}</b></td>\r\n							<td align=\"right\"><b>{{totalused|number_format(1, \'.\', \',\')}} KG</b></td>\r\n							\r\n					      	\r\n					     </tr>\r\n					\r\n				</tfoot>\r\n</table>\r\n{% partial \'button\' url=\'http://bailaerp.bt-industrial.co.za/report/download/inventory/today.pdf\' type=\'positive\' body %}\r\nDownload\r\n{% endpartial %}\r\n\r\n{% partial \'button\' url=\'http://bailaerp.bt-industrial.co.za/inventory/rawreceiving\' type=\'positive\' body %}\r\nView More\r\n{% endpartial %}\r\n\r\n<br>\r\n<h1>Production</h1>\r\n<table class=\"\" style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellspacing=\"0px\" cellpadding=\"2px\"  border=\"1\">\r\n				<tr>\r\n					<th colspan=\"2\"></th>\r\n					<th class=\"text-center\" colspan=\"2\">TARGETS</th>\r\n					<th class=\"text-center\" colspan=\"5\">ACTUAL</th>\r\n					<th class=\"text-center\" colspan=\"6\">DEVIATIONS</th>\r\n				</tr>\r\n				<tr>\r\n					<th>Name</th>\r\n					<th nowrap>Date</th>\r\n					<th nowrap>KG <br>Processed</th>\r\n					<th nowrap>Units <br>Produced</th>\r\n					<th nowrap>KG <br>Processed</th>\r\n					<th nowrap>Units <br>Produced</th>\r\n					<th nowrap>Units <br>Passed QC</th>\r\n					<th nowrap>Weight of <br>Scrap</th>\r\n					<th nowrap>Over <br>Weight</th>\r\n					<th nowrap>Reason<br>KG processed</th>\r\n					<th nowrap>Reason<br>QC Fail</th>\r\n					<th nowrap>Reason<br>Overweight</th>\r\n					<th nowrap>Recovery <br>Plan</th>\r\n					<th nowrap>Material <br>Used</th>\r\n					<th nowrap>Maintenance/Technical</th>\r\n				</tr>\r\n			</thead>\r\n<tbody>\r\n{% for item in tblproduction %}\r\n	<tr>\r\n		<tr>\r\n			<td style=\"font-size: 10px;\" nowrap><a href=\"http://portal.bt-industrial.co.za/production/{{item.pipe.push_id}}/{{item.pipe_id}}\">{{item.pipe.quoteitems.description}}</a></td>     		\r\n			<td nowrap style=\"font-size: 10px;\">{{item.production_date}}</td>\r\n			<td style=\"font-size: 10px;\">{{item.target_kg_processed}}</td>\r\n			<td style=\"font-size: 10px;\">{{item.target_units_produced}}</td>\r\n			<td style=\"font-size: 10px;\">{{item.total_kg_processed}}</td> \r\n			<td style=\"font-size: 10px;\">{{item.total_units_produced}}</td> \r\n			<td style=\"font-size: 10px;\">{{item.total_units_passed_qc}}</td>\r\n			<td style=\"font-size: 10px;\">{{item.weight_scrap_kg}} kg</td> \r\n			<td style=\"font-size: 10px;\">{{item.over_weight_kg}} kg</td> \r\n			<td style=\"font-size: 10px;\">{{item.reason_deviation_processed}}</td>\r\n			<td style=\"font-size: 10px;\">{{item.reason_qc_Fail}}</td>\r\n			<td style=\"font-size: 10px;\">{{item.reason_overweight}}</td> \r\n			<td style=\"font-size: 10px;\">{{item.recovery_plan}}</td>\r\n			<td style=\"font-size: 10px;\">{{item.running_hours}}</td>\r\n			<td style=\"font-size: 10px;\">{{item.maintenance}}</td>\r\n			\r\n	     </tr>\r\n	     </tr>\r\n	</tr>\r\n{% else %}\r\n    <tr>\r\n		<td colspan=\"2\">No Item</td>\r\n	</tr>\r\n{% endfor %}\r\n</tbody> \r\n</table>\r\n<br><br>\r\n<h1>Pipes On The Floor</h1>\r\n\r\n<table class=\"\" style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellspacing=\"0px\" cellpadding=\"2px\"  border=\"1\">\r\n<thead>\r\n	<tr>\r\n		<th>Client</th>\r\n		<th>Quote</th>\r\n						<th>Pipe Description</th>\r\n						<th>Status</th>\r\n						<th>Start Date</th>\r\n						<th align=\"right\">Unit Price</th>\r\n						<th align=\"right\">Price Per KG</th>\r\n						<th align=\"right\">Weight</th>\r\n						<th align=\"right\">Target</th>\r\n						<th align=\"right\">Units</th>\r\n		        		<th align=\"right\">On Floor</th>\r\n		        		<th align=\"right\">On Floor Price</th>\r\n		        		<th align=\"right\">Delivered</th>\r\n		        		<th  align=\"right\">Scrap</th>\r\n		        		<th  align=\"right\">Material Used</th>\r\n	</tr>\r\n</thead>\r\n<tbody>\r\n				\r\n					{% set totalscrap = 0 %}\r\n					{% set totalmaterial = 0 %}\r\n					{% set totalunites = 0 %}\r\n					{% set totaldelivered = 0 %}\r\n					{% set totalfloor = 0 %}\r\n					{% set totalfloorprice = 0 %}					\r\n			        {% for item in tblfloorpipes if item.active == 1 %}\r\n						<tr>\r\n			        		\r\n			        		\r\n			        		<td>{{item.qpush.quote.company_name}}</td>\r\n			        		<td>{{item.qpush.quote.id}}\r\n			        			\r\n			        		</td>\r\n			        		<td ><a target=\"_blank\" href=\"/pipe/item/download/{{item.id}}\">{{item.quoteitems.description}}</a></td>\r\n			        		<td>{{item.qpush.status.name}}</td>\r\n			        		<td>{{item.start_date}}</td>\r\n			        		<td align=\"right\">R {{item.quoteitems.unitprice|number_format(2, \'.\', \',\')}}</td>\r\n			        		<td align=\"right\">R {{item.quoteitems.priceperkg|number_format(2, \'.\', \',\')}}</td>\r\n			        		<td align=\"right\">{{item.quoteitems.weight}} kg</td>\r\n			        		<td align=\"right\">{{item.quoteitems.units}}</td>\r\n			        		<td align=\"right\">{{item.schedules().sum(\'total_units_passed_qc\')}}</td>\r\n			        		\r\n			        		<td align=\"right\">{{item.schedules().sum(\'total_units_passed_qc\') - item.delivered().sum(\'units\')}}</td>\r\n\r\n			        		<td align=\"right\">R {{((item.schedules().sum(\'total_units_passed_qc\') - item.delivered().sum(\'units\')) * item.quoteitems.unitprice)|number_format(2, \'.\', \',\')}}</td>\r\n\r\n			        		<td align=\"right\">{{item.delivered().sum(\'units\')}}</td>\r\n			        		<td align=\"right\">{{item.schedules().sum(\'weight_scrap_kg\')}} kg</td>\r\n			        		<td align=\"right\">\r\n			        		{% set total_auto_used = 0 %}\r\n								{% for sc in item.schedules %}\r\n									{% for rl in sc.usedmaterials %}\r\n										{% set total_auto_used = total_auto_used + rl.kg %}\r\n									{% endfor %} \r\n								{% endfor %} \r\n								{{total_auto_used}} kg\r\n							</td>\r\n\r\n			        		{% set totalscrap = totalscrap + item.schedules().sum(\'weight_scrap_kg\') %}\r\n							{% set totalunites = totalunites + item.schedules().sum(\'total_units_passed_qc\') %}\r\n							{% set totaldelivered = totaldelivered + item.delivered().sum(\'units\') %}\r\n							{% set totalfloor = totalfloor + (item.schedules().sum(\'total_units_passed_qc\') - item.delivered().sum(\'units\')) %}\r\n\r\n							{% set totalfloorprice = totalfloorprice + ((item.schedules().sum(\'total_units_passed_qc\') - item.delivered().sum(\'units\')) * item.quoteitems.unitprice) %}\r\n\r\n							{% set totalmaterial = totalmaterial + total_auto_used %}\r\n\r\n			        		\r\n			             </tr>\r\n			        {% endfor %} \r\n		        </tbody>\r\n				<tfoot>\r\n					<tr>\r\n						<td align=\"right\" colspan=\"7\"><b>TOTAL</b></td>\r\n						<td align=\"right\"><b>{{totalunites}}</b></td>\r\n						<td align=\"right\"><b>{{totalfloor}}</b></td>\r\n						<td align=\"right\"><b>R {{totalfloorprice|number_format(2, \'.\', \',\')}}</b></td>\r\n						<td align=\"right\"><b>{{totaldelivered}}</b></td>\r\n						<td align=\"right\"><b>{{totalscrap|number_format(1, \'.\', \',\')}} kg</b></td>\r\n						<td align=\"right\"><b>{{totalmaterial|number_format(1, \'.\', \',\')}} kg</b></td>\r\n						\r\n				      	\r\n				     </tr>\r\n\r\n				</tfoot> \r\n</table>\r\n\r\n{% partial \'button\' url=\'http://bailaerp.bt-industrial.co.za/report/download/pipes/today.pdf\' type=\'positive\' body %}\r\nDownload\r\n{% endpartial %}\r\n\r\n{% partial \'button\' url=\'http://portal.bt-industrial.co.za\' type=\'positive\' body %}\r\nView More\r\n{% endpartial %}\r\n\r\n<h1>Maintenance Schedule</h1>\r\n\r\n<table class=\"\" style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellspacing=\"0px\" cellpadding=\"2px\"  border=\"1\">\r\n<thead>\r\n	<tr>\r\n		<th width=\"2%\" style=\"background: #ececec\">#</th>\r\n		<th width=\"8%\" style=\"background: #ececec\">Plant Item</th>	\r\n		<th width=\"5%\" style=\"background: #ececec\">Action</th>\r\n		<th width=\"7%\" style=\"background: #ececec\">Date</th>		\r\n		<th width=\"29%\" style=\"background: #ececec\">Summary</th>\r\n		<th width=\"29%\" style=\"background: #ececec\">Instruction Notes</th>\r\n		<th width=\"13%\" style=\"background: #ececec\">Spares</th>\r\n		<th width=\"7%\" style=\"background: #ececec;text-align: right\">Budget</th>\r\n	</tr>\r\n</thead>\r\n<tbody>\r\n				\r\n						{% set counter = 0 %}\r\n						{% set total = 0 %}\r\n				        {% for itemobject in tblmaintainace %}\r\n				        	{% set counter = counter + 1 %}\r\n				        	<tr>\r\n				        		<td>{{counter}}</td>\r\n								<td>{{itemobject.btline.name}}</td>\r\n								<td>{{itemobject.actiontype.name}}</td>\r\n								<td>{{itemobject.scheduledate|date(\"d M Y\")}}</td>\r\n								<td>{{itemobject.job_summary}}</td>\r\n								<td>{{itemobject.instruction_notes}}</td>\r\n								<td>{{itemobject.spares_used}}</td>\r\n								<td style=\"text-align: right\">R{{itemobject.budget|number_format(2, \'.\', \',\')}}</td>\r\n								{% set total = total + itemobject.budget %}\r\n				        		\r\n				             </tr>\r\n				        {% endfor %} \r\n		        </tbody>\r\n				<tfoot>\r\n					 <tfoot>\r\n			        	<tr>\r\n			        		<td style=\"background: #ececec;text-align: right\" colspan=\"7\"><b>Total</b></td>\r\n			        		<td style=\"background: #ececec;text-align: right\"><b>R{{total|number_format(2, \'.\', \',\')}}</b></td>\r\n			        	</tr>\r\n			        	\r\n			        </tfoot>\r\n\r\n				</tfoot> \r\n</table>\r\n\r\n{% partial \'button\' url=\'http://bailaerp.bt-industrial.co.za/maintenance/item/download/schedule.pdf\' type=\'positive\' body %}\r\nDownload\r\n{% endpartial %}\r\n\r\n{% partial \'button\' url=\'http://bailaerp.bt-industrial.co.za/maintenance/schedule\' type=\'positive\' body %}\r\nView More\r\n{% endpartial %}\r\n\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',3,1,'2019-05-30 12:26:43','2021-04-07 14:02:41'),(14,'BT.sales.material.requestrelease','Raw Material Request: {{ref}}','Raw Material Request: {{ref}}','Hi {{ to_name }},\r\n\r\n{{sales_name}} is requesting a release of material. Here are the details below:\r\n\r\n**Product Name:** {{product_name}}.\r\n\r\n**Batch Number:** {{supplier_batch}}. \r\n\r\n**Weight In KG:** {{kg}} kg\r\n\r\n**Reason for release:** {{reason}}\r\n\r\n**Expected date and time:** {{requesteddate}}\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2019-07-07 09:23:29','2019-08-01 00:44:50'),(15,'BT.sales.response.productionnotify','Request: Sales production Nofity {{ref}}','Request: Sales production Nofity {{ref}}','Hi {{ to_name }},\r\n\r\nNew production request:\r\n\r\n**Company Name:** {{company_name}}.\r\n\r\n**Quote Refence:** {{ref}}. \r\n\r\n**Quote Total:** R{{quote_total}}\r\n\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2019-07-14 22:51:11','2019-08-01 00:46:06'),(16,'bt.notify.production.jobcardapproval','BT Industrial Production Jobcard Approval: {{ref}}','bt.notify.production.jobcardapproval','Hi {{ name }},\r\n\r\n{{username}} is requesting a production jobcard approval. Please find the attached jobcard.\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2019-08-11 09:08:49','2019-08-11 09:21:54'),(17,'bt.notify.production.productionapproval','BT Industrial Production Approval: {{ref}}','BT Industrial Production Approval: {{ref}}','Hi {{ name }},\r\n\r\n{{username}} is requesting a production approval. Please find the attached quote details.\r\n\r\n**Invoice:** {{push.quote.invoice.name}}.\r\n\r\n**Client Name:** {{push.quote.company_name}}. \r\n\r\n**Client Utilization:** {{push.quote.client.utilization}}. \r\n\r\n**Client limit:** {{push.quote.client.limit}}. \r\n\r\n**Client Category:** {{push.quote.client.client_category.name}}. \r\n\r\n<table class=\"\" style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellspacing=\"0px\" cellpadding=\"2px\"  border=\"1\">\r\n<thead>\r\n	<tr>\r\n		<th width=\"20%\" style=\"background: #ececec\">Description</th>	\r\n		<th width=\"10%\" style=\"background: #ececec\">Price/KG</th>\r\n		<th width=\"10%\" style=\"background: #ececec\">Units</th>\r\n		<th width=\"10%\" style=\"background: #ececec\">Unit Price</th>		\r\n		<th width=\"10%\" style=\"background: #ececec\">Unit Lenght</th>\r\n		<th width=\"10%\" style=\"background: #ececec\">Total Lenght</th>\r\n		<th width=\"10%\" style=\"background: #ececec\">Weight</th>\r\n		<th width=\"10%\" style=\"background: #ececec\">Total Weight</th>\r\n		<th width=\"10%\" style=\"background: #ececec;text-align: right\">Total Price</th>\r\n	</tr>\r\n</thead>\r\n<tbody>\r\n    {% for itemobject in push.quote.items %}\r\n        <tr>\r\n    		\r\n    		<td>{{itemobject.description}}</td>\r\n    		<td>{% if itemobject.product.value > 0 and itemobject.unitlength > 0 %}\r\n{{((itemobject.unitprice/itemobject.product.value)/itemobject.unitlength)|number_format(2, \'.\', \',\')}}\r\n{% endif %}</td>\r\n    		<td>{{itemobject.units}}</td>\r\n    		<td>R{{itemobject.unitprice|number_format(2, \'.\', \',\')}}</td>\r\n    		<td>{{itemobject.unitlength}}</td>\r\n    		<td>{{itemobject.unitlength * itemobject.units}}</td>\r\n    		<td>{{itemobject.weight}}</td>\r\n    		<td>{{itemobject.totalweight}}</td>\r\n    		<td style=\"text-align: right\">R{{itemobject.price|number_format(2, \'.\', \',\')}}</td>\r\n    	\r\n    		\r\n             </tr>\r\n    {% endfor %} \r\n</tbody>\r\n \r\n</table>\r\n\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2019-08-11 11:24:12','2022-05-10 07:19:57'),(18,'bt.notify.purchase.approval','BT Industrial PO Approval: {{ref}}','bt.notify.purchase.approval','Hi {{ name }},\r\n\r\n{{username}} is requesting a material PO for approval.\r\n\r\n**Supplier Name:** {{purchase.supplier.name}}. \r\n\r\n**Weight:** {{purchase.weight}} kg.\r\n\r\n**Total Price:** R {{purchase.price|number_format(2, \'.\', \',\')}}.\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2019-08-11 22:53:00','2019-08-11 22:58:04'),(19,'bt.notify.sales.deliveryplan','BT Industrial Delivery Schedule Notify: {{ref}}','BT Industrial Delivery Schedule Notify: {{ref}}','Hi {{ name }},\r\n\r\n{{username}} has scheduled delivery. Please see the details below:\r\n\r\n**Client Name:** {{delivery.client.company_name}}\r\n\r\n**BT Qoute Number: ** {{delivery.quote_id}}\r\n\r\n**Invoice Number:** {{invoice}}\r\n\r\n**Type:** {{delivery.type.name}}\r\n\r\n**Note:** {{delivery.notes}}\r\n\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2019-08-30 00:57:43','2020-02-13 09:55:09'),(20,'janvince.smallcontactform::mail.autoreply',NULL,NULL,NULL,NULL,1,0,'2020-02-09 09:46:06','2020-02-09 09:46:06'),(21,'janvince.smallcontactform::mail.notification',NULL,NULL,NULL,NULL,1,0,'2020-02-09 09:46:06','2020-02-09 09:46:06'),(22,'BT.sales.response.notifyinvoice','Request: Create Quote Invoice {{ref}}','Request: Create Quote Invoice {{ref}}','Hi {{ to_name }},\r\n\r\n{{sales_name}} is requesting Finance to create invoice. Here are the Details below:\r\n\r\n**Company Name:** {{company_name}}.\r\n\r\n**Quote Refence:** {{ref}}. \r\n\r\n**Quote Total:** R{{quote_total}}\r\n\r\n**Message:** {{notes}}\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2020-02-09 09:52:30','2020-02-10 10:42:43'),(23,'BT.finance.requisition.notify','Request Requisition {{ref}}','Request Requisition {{ref}}','Hi {{ to_name }},\r\n\r\n{{sales_name}} is requesting requisition approval. Here are the Details below:\r\n\r\n**Refence:** {{ref}}. \r\n\r\n**Supplier Name:** {{quote.suppliername}}.\r\n\r\n**Date:** {{quote.req_date}}\r\n\r\n**Amount:** R{{quote.amount}}\r\n\r\n**Description:** {{quote.description}}\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2020-02-21 08:23:24','2020-02-21 08:23:24'),(24,'bt.notify.production.productioncanceled','BT Production Canceled: {{ref}}','BT Production Canceled: {{ref}}','Hi {{ name }},\r\n\r\n{{sales_name}} has canceled production. Please find details below:\r\n\r\n**Quote Id:** {{push.quote.id}}.\r\n\r\n**Invoice Id:** {{push.quote.invoice.name}}.\r\n\r\n**Client Name:** {{push.quote.company_name}}. \r\n\r\n**Description:** {{notes}}\r\n\r\n<table class=\"\" style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellspacing=\"0px\" cellpadding=\"2px\"  border=\"1\">\r\n<thead>\r\n	<tr>\r\n		<th width=\"20%\" style=\"background: #ececec\">Description</th>	\r\n		<th width=\"10%\" style=\"background: #ececec\">Price/KG</th>\r\n		<th width=\"10%\" style=\"background: #ececec\">Units</th>\r\n		<th width=\"10%\" style=\"background: #ececec\">Unit Price</th>		\r\n		<th width=\"10%\" style=\"background: #ececec\">Unit Lenght</th>\r\n		<th width=\"10%\" style=\"background: #ececec\">Total Lenght</th>\r\n		<th width=\"10%\" style=\"background: #ececec\">Weight</th>\r\n		<th width=\"10%\" style=\"background: #ececec\">Total Weight</th>\r\n		<th width=\"10%\" style=\"background: #ececec;text-align: right\">Total Price</th>\r\n	</tr>\r\n</thead>\r\n<tbody>\r\n    {% for itemobject in push.quote.items %}\r\n        <tr>\r\n    		\r\n    		<td>{{itemobject.description}}</td>\r\n    		<td>{% if itemobject.product.value > 0 and itemobject.unitlength > 0 %}\r\n{{((itemobject.unitprice/itemobject.product.value)/itemobject.unitlength)|number_format(2, \'.\', \',\')}}\r\n{% endif %}</td>\r\n    		<td>{{itemobject.units}}</td>\r\n    		<td>R{{itemobject.unitprice|number_format(2, \'.\', \',\')}}</td>\r\n    		<td>{{itemobject.unitlength}}</td>\r\n    		<td>{{itemobject.unitlength * itemobject.units}}</td>\r\n    		<td>{{itemobject.weight}}</td>\r\n    		<td>{{itemobject.totalweight}}</td>\r\n    		<td style=\"text-align: right\">R{{itemobject.price|number_format(2, \'.\', \',\')}}</td>\r\n    	\r\n    		\r\n             </tr>\r\n    {% endfor %} \r\n</tbody>\r\n \r\n</table>\r\n\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2020-02-23 09:53:54','2020-02-23 11:18:24'),(25,'BT.production.completed','Production Completed: Quote {{quote_id}}','Production Completed: Quote {{quote_id}}','Hi {{ name }},\r\n\r\nProduction has been completed\r\n\r\n**Client Name:** {{report.quote.company_name}}. \r\n\r\n**Invoice Id:** {{report.quote.invoice.name}}.\r\n\r\n**Quote Id:** {{report.quote.id}}.\r\n\r\n**PO Number:** {{report.quote.ponumber}}.\r\n\r\n<h3>SUMMARY</h3>\r\n						{% set counter = 0 %}\r\n						<table class=\"\" style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellspacing=\"0px\" cellpadding=\"2px\"  border=\"1\">\r\n							<thead>\r\n								<tr>\r\n									<th width=\"20px\" class=\"text-left\">#</th>\r\n									<th class=\"text-left\" >Description</th>		\r\n									<th width=\"50px\" nowrap=\"nowrap\" class=\"text-center\" >Units</th>	\r\n									\r\n								</tr>\r\n							</thead>\r\n						\r\n						{% set productionunits = 0 %}\r\n				        {% for itemobject in report.quote.items %}\r\n				        	{% set counter = counter + 1 %}\r\n				        	\r\n						        	<tr>\r\n						        		<td>{{counter}}</td>\r\n						        		<td>{{itemobject.description}}</td>		\r\n						        		<td width=\"50px\" class=\"text-center\">{{itemobject.units}}</td>	\r\n						        		\r\n						             </tr>\r\n						         	{% set productionunits = productionunits + itemobject.units %}\r\n				        {% endfor %} \r\n\r\n				   \r\n				         {% for itemobject in report.quote.itemscat %}\r\n				        	{% set counter = counter + 1 %}\r\n				        		<tr>\r\n					        		<td>{{counter}}</td>\r\n					        		<td>{{itemobject.description}}</td>		\r\n					        		<td width=\"50px\" class=\"text-center\">{{itemobject.units}}</td>	\r\n								</tr>\r\n				        {% endfor %}\r\n				        </table>\r\n				        <br>\r\n				        <h3>DELIVERY SUMMARY</h3>\r\n						<table class=\"\" style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellspacing=\"0px\" cellpadding=\"2px\"  border=\"1\">\r\n							<thead>\r\n								<tr>\r\n									<th width=\"150px\" class=\"text-left\">Date</th>\r\n									<th class=\"text-left\" >Type</th>		\r\n									<th width=\"50px\" nowrap=\"nowrap\" class=\"text-center\" >Units</th>	\r\n								</tr>\r\n							</thead>\r\n				        <!-- Set Delevery -->\r\n					    	{% set productionudelivered = 0 %}\r\n				        	{% for itemobject in report.quote.srn %}\r\n						        	<tr>\r\n						        		<td>{{itemobject.schedule_date|date(\"Y-m-d\")}}</td>\r\n						        		<td>{{itemobject.type.name}}</td>		\r\n						        		<td class=\"text-center\">{{itemobject.items().sum(\'units\')}}</td>\r\n						             </tr>\r\n						         	{% set productionudelivered = productionudelivered + itemobject.items().sum(\'units\') %}\r\n				        	{% endfor %} \r\n				        	<tfoot>\r\n				        		<tr>\r\n				        			<td colspan=\"2\"><b>Total</b></td>\r\n				        			<td class=\"text-center\"><b>{{productionudelivered}}</b></td>\r\n				        		</tr>\r\n				        	</tfoot>\r\n				        </table>\r\n				        <br>\r\n				        <h3>PRODUCTION</h3>\r\n				        \r\n				        \r\n				        \r\n				        {% set chartid = 0 %}\r\n		{% for pipes in report.quote.qpush.pipes %}\r\n			{% set chartid = chartid + 1 %}\r\n			<br>\r\n					<h3 style=\"background: #ccc; padding: 5px 10px; border-bottom: #000\">{{chartid}}: {{pipes.quoteitems.description}} </h3>\r\n			\r\n					<table class=\"\" style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellspacing=\"0px\" cellpadding=\"2px\"  border=\"1\">\r\n						<tr>\r\n							<td width=\"15%\"><b>Item:</b></td><td  width=\"35%\">{{pipes.quoteitems.description}}</td>\r\n							<td width=\"15%\"><b>Unit To Produce:</b></td><td>{{pipes.quoteitems.units}}</td>\r\n						</tr>\r\n						<tr>\r\n							<td><b>Start Date:</b></td><td>{{pipes.start_date|date(\"Y-m-d\")}}</td>\r\n							<td><b>Due Date:</b></td><td>{{pipes.due_date|date(\"Y-m-d\")}}</td>\r\n						</tr>\r\n						<tr>\r\n							<td ><b>Unit Produced:</b></td><td>{{pipes.schedules().sum(\'total_units_passed_qc\')}}</td>\r\n								<td ><b>Production Progress:</b></td>\r\n								<td >\r\n						\r\n								</td>\r\n							</tr>\r\n					</table>\r\n				<br>\r\n				\r\n				{% set total = 0 %}\r\n				{% set datagraph_kg = [] %}\r\n				{% set datagraph_units = [] %}\r\n				{% set seriesgraph_kg = [] %}\r\n\r\n				{% set t_target_units_produced = [] %}\r\n				{% set t_total_units_produced = [] %}\r\n				{% set t_total_units_passed_qc = [] %}\r\n				{% set t_total_units_fail_qc = [] %}\r\n				{% set t_Running_total_of_failed_pipes = [] %}\r\n				{% set t_Running_total_of_pipes_produced = [] %}\r\n				{% set t_Running_total_of_passed_Units = [] %}\r\n\r\n				{% set t_target_kg_processed = [] %}\r\n				{% set t_total_kg_processed = [] %}\r\n				{% set t_weight_scrap_kg = [] %}\r\n				{% set t_Running_total_of_weight_processed_kg = [] %}\r\n				{% set t_over_weight_kg = [] %}\r\n				{% set t_Wasted_material_kg = [] %}\r\n\r\n				<table class=\"\" style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellspacing=\"0px\" cellpadding=\"2px\"  border=\"1\">\r\n					<thead>\r\n						<tr>\r\n							<th>Date</th>\r\n							<th>Units Produced</th>\r\n							<th>Runnning Total</th>\r\n						</tr>\r\n					</thead>\r\n					<tbody>\r\n						\r\n							{% for item in pipes.schedules if item.total_units_passed_qc > 0 %}\r\n\r\n				        		{% set usedate = item.production_date|date(\"m/d/Y 00:00:00\", false) %}\r\n					        	{% set usedate = (usedate| date(\'U\')) *1000 + 2*3600*1000 %} \r\n\r\n								<tr class=\"{{(item.total_kg_processed > 0)?\'\':\'text-warning\'}}\">\r\n					        		<td nowrap=\"nowrap\" >{{item.production_date}}</td>\r\n									<td>{{item.total_units_passed_qc}}</td> \r\n									\r\n									<td>{% set Running_total_of_passed_Units = Running_total_of_passed_Units + item.total_units_passed_qc %}\r\n									{{Running_total_of_passed_Units}}</td> \r\n									 \r\n					             </tr>\r\n\r\n				             {% set t_total_units_passed_qc = t_total_units_passed_qc|merge([[usedate, item.total_units_passed_qc]]) %}\r\n\r\n					        	{% set t_Running_total_of_passed_Units = t_Running_total_of_passed_Units|merge([[usedate, Running_total_of_passed_Units]]) %}\r\n\r\n				        {% endfor %} \r\n				        \r\n				         \r\n				    </tbody>\r\n				</table>\r\n\r\n\r\n		{% endfor %} \r\n		\r\n{{response_details}}\r\n<br>\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2020-05-23 22:22:43','2020-05-23 22:35:16'),(26,'BT.sales.response.srnaprove','Request: SRN Approval {{ref}}','Request: SRN Approval {{ref}}','Hi {{ to_name }},\r\n\r\n{{sales_name}} is requesting QC to approve the SRN. Here are the Details below:\r\n\r\n**Company Name:** {{company_name}}.\r\n\r\n**Quote Refence:** {{ref}}. \r\n\r\n**Message:** Stock ordered is ready for collection or delivery.\r\n\r\n**Notification Date and Time:** {{ \"now\"|date(\"m/d/Y H:i\") }}\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2020-06-11 13:02:09','2023-10-20 08:36:55'),(27,'bt.checklist.notify','Checklist Notify','bt.checklist.notify','Hi {{ name }},\r\n\r\nNotification Date and Time: {{ \"now\"|date(\"m/d/Y H:i\") }} \r\n{% for checklistitem in checklist if checklistitem.status_id == 1 %}\r\n    <h2 style=\"margin-top: 10px\">{{checklistitem.checklist.name}} Check List</h2>\r\n	<table width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n		<tr>\r\n		<td width=\"47%\" valign=\"top\">\r\n			<table width=\"100%\" border=\"0\" cellpadding=\"5px\" cellspacing=\"0\">\r\n				<tr><td  colspan=\"2\" style=\"background: #ccc\"  ><b>Check List Details:</b></td></tr>\r\n				<tr><td width=\"50%\"><b>Schedule Date:</b></td><td width=\"50%\">{{checklistitem.scheduledate|date(\"Y-m-d\")}}\r\n							</td></tr>\r\n				<tr><td width=\"50%\"><b>Instructions:</b></td><td width=\"50%\">{{checklistitem.instructions}}</td></tr>\r\n				<tr><td width=\"50%\"><b>Assigned To:</b></td><td width=\"50%\">{{checklistitem.assignedto.name}}</td></tr>\r\n				<tr><td width=\"50%\"><b>Status:</b></td><td width=\"50%\">{{checklistitem.status.name}}</td></tr>\r\n				</table>\r\n		</td>\r\n		<td></td>\r\n		<td width=\"47%\" valign=\"top\">\r\n			<table width=\"100%\" border=\"0\" cellpadding=\"5px\" cellspacing=\"0\">\r\n\r\n				<tr><td colspan=\"2\" style=\"background: #ccc\"  ><b>Tool/Equipment Details:</b></td></tr>\r\n				<tr><td width=\"50%\"><b>Equipment Type:</b></td><td width=\"50%\">{{checklistitem.tool.equipment_type.name}}</td></tr>\r\n				{% if quote.partcode is not empty %}\r\n					<tr><td width=\"50%\"><b>Part Code:</b></td><td width=\"50%\">{{checklistitem.tool.partcode}}</td></tr>\r\n				{% endif %}\r\n				<tr><td width=\"50%\"><b>Equipment Description:</b></td><td width=\"50%\">{{checklistitem.tool.name}}</td></tr>\r\n\r\n				\r\n				{% if quote.make is not empty %}\r\n					<tr><td width=\"50%\" valign=\"top\" ><b>Make:</b></td><td width=\"50%\">{{checklistitem.tool.make}}</td></tr>\r\n				{% endif %}\r\n				{% if quote.serialnumber is not empty %}\r\n					<tr><td width=\"50%\" valign=\"top\" ><b>Serial Number:</b></td><td width=\"50%\">{{checklistitem.tool.serialnumber}}</td></tr>\r\n				{% endif %}\r\n				{% if quote.modelnumber is not empty %}\r\n					<tr><td width=\"50%\" valign=\"top\" ><b>Model Number:</b></td><td width=\"50%\">{{checklistitem.tool.modelnumber}}</td></tr>\r\n				{% endif %}\r\n				\r\n				{% if quote.suppliername is not empty %}\r\n					<tr><td width=\"50%\" valign=\"top\" ><b>Manufacture/Supplier:</b></td><td width=\"50%\">{{checklistitem.tool.suppliername}}</td></tr>\r\n				{% endif %}\r\n			\r\n			</table>\r\n		</td>\r\n	</tr>\r\n	<tr>\r\n	<td><a href=\"http://bailaerp.bt-industrial.co.za/checklist/item/download/{{checklistitem.tool.id}}/{{checklistitem.id}}.pdf\">\r\nDownload Checkist</a></td>\r\n	<td></td>\r\n	<td><a href=\"http://bailaerp.bt-industrial.co.za/backend/bt/maintenance/tools/update/{{checklistitem.tool.id}}\">View Tool </a></td>\r\n	</tr>\r\n</table>\r\n\r\n\r\n\r\n\r\n{% endfor %} \r\n\r\n\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2020-06-17 14:21:14','2020-06-17 14:21:14'),(28,'bt.notify.sales.returnnotes','BT Return Note','bt.notify.sales.returnnotes','Hi {{ to_name }},\r\n\r\nHere in the Return Notification of stock from {{from_name}}:\r\n\r\n**Company Name:** {{company_name}}.\r\n\r\n**Quote #:** {{quote_id}}. \r\n\r\n**SRN:** {{srn_id}}. \r\n\r\n<table class=\"\" style=\"width: 100%;border-collapse:collapse; border: 1px solid #ccc; border-color: #ccc\" cellspacing=\"0px\" cellpadding=\"5px\"  border=\"1\">\r\n<thead>\r\n    <tr><th>#</th><th>Date</th><th>Description</th><th>Units Returned</th><th>Reason</th></tr>\r\n    </thead>\r\n	{% for item in tblrns %}\r\n	    <tr>\r\n	        <td>{{item.id}}</td>\r\n	        <td>{{item.return_date}}</td>\r\n	        <td>{{item.items.id}}: {{item.items.pipe.quoteitems.description}}</td>\r\n	        <td>{{item.units}}</td>\r\n	        <td>{{item.note}}</td>\r\n	   </tr>\r\n	    \r\n	{% endfor%}\r\n</table>\r\n\r\n\r\n\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2020-07-09 14:02:04','2020-07-09 14:02:04'),(29,'bt.notify.srn','BT HDPE: PAST 7 DAYS SRN NOTIFY','BT SRN Notify','Hi {{ name }},\r\n\r\nNotification Date and Time: {{ \"now\"|date(\"m/d/Y H:i\") }} \r\n\r\n\r\n<h1>SRN</h1>\r\n<div >\r\n<table  style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellpadding=\"4px\" border=\"1px\">\r\n<thead>\r\n	<tr>\r\n		<th>#</th>\r\n		<th>#</th>\r\n        <th nowrap=\"nowrap\">Schedule Date</th>\r\n			 	<th nowrap=\"nowrap\">Marked Completed</th>\r\n		<th nowrap=\"nowrap\">Quote</th>\r\n	\r\n		<th nowrap=\"nowrap\">Client</th>\r\n		<th nowrap=\"nowrap\">Invoice</th>\r\n		<th nowrap=\"nowrap\">Type</th>\r\n		<th nowrap=\"nowrap\">Delivery Cost</th>\r\n        <th nowrap=\"nowrap\">Items</th>\r\n        <th nowrap=\"nowrap\">Value</th>\r\n        <th nowrap=\"nowrap\">SRN</th>\r\n		<th nowrap=\"nowrap\">QC SRN</th>\r\n        <th nowrap=\"nowrap\">DN</th>\r\n        <th nowrap=\"nowrap\">CN</th>\r\n        <th nowrap=\"nowrap\">Images</th>\r\n        \r\n        \r\n	</tr>\r\n</thead>\r\n<tbody>\r\n	{% set totalpricevalue = 0 %}\r\n	{% set totalcount = 0 %}\r\n    {% for item in tblsrn %}\r\n        {% set checkif = 0 %}\r\n        {% for itemobject in item.files_srn %}\r\n					{% set checkif = checkif + 1 %}\r\n	    {% endfor %}\r\n			{% for itemobject in item.files_delivery %}\r\n					{% set checkif = checkif + 1 %}\r\n			 {% endfor %}\r\n			{% for itemobject in item.files_collection %}\r\n					{% set checkif = checkif + 1 %}\r\n			      {% endfor %}\r\n		\r\n		 {% if item.type.id == 1 and item.deliveryprice < 1%}\r\n		        {% set checkif = 0 %}\r\n		    {% endif %}\r\n			      \r\n		<tr>\r\n		    {% if checkif > 1%}\r\n		        <td></td>\r\n		    {% else %}\r\n		        <td nowrap=\"nowrap\" style=\"background-color: red; color: #ffffff\">Incomplete</td>\r\n		    {% endif %}\r\n		    \r\n			<td nowrap=\"nowrap\">\r\n			<a href=\"http://bailaerp.bt-industrial.co.za/backend/bt/sales/srn/update/{{item.id}}\">{{item.id}}</a></td>\r\n			<td nowrap=\"nowrap\">{{item.schedule_date|date(\"m/d/Y\")}}</td>\r\n		<td>\r\n			{{(item.active == 1)?\'Yes\':\'No\'}}\r\n	</td>\r\n			<td>{{item.quote_id}}</td>\r\n			\r\n			\r\n			<td>{{item.client.company_name}}</td>\r\n			\r\n			<td>\r\n				{% for inv in item.srninvoice %}\r\n					{{inv.name}}  \r\n				{% endfor %}\r\n			</td>\r\n			<td>{{item.type.name}}</td>\r\n		\r\n			 {% if item.type.id == 1 and item.deliveryprice < 1%}\r\n		        <td nowrap=\"nowrap\"  style=\"background-color: red; color: #ffffff;text-align: right;\">R {{item.deliveryprice|number_format(2, \'.\', \',\')}}</td>\r\n		    {% else %}\r\n		        <td nowrap=\"nowrap\" style=\"text-align: right;\">R {{item.deliveryprice|number_format(2, \'.\', \',\')}}</td>\r\n		    {% endif %}\r\n			 \r\n			<td>\r\n				\r\n				{% set counter = 0 %}\r\n				{% set pricevalue = 0 %}\r\n		        {% for itemobject in item.items %}\r\n		        	{% set counter = counter + 1 %}\r\n		        	{% set pricevalue = pricevalue + itemobject.pipe.quoteitems.unitprice*itemobject.units %}\r\n		        	\r\n    	\r\n	        		{% if itemobject.description is not empty %}\r\n	        			{{itemobject.description}}\r\n	        		{% else %}\r\n	        			{{itemobject.pipe.quoteitems.description}}\r\n	        		{% endif %}	\r\n	        		 X <b>\r\n	        		{% if itemobject.unitdescription is not empty %}\r\n	        			{{itemobject.unitdescription}}\r\n	        		{% else %}\r\n	        		{% set totalcount = totalcount + itemobject.units %}\r\n	        			{{itemobject.units}}\r\n	        		{% endif %}	\r\n	        		<br></b>	\r\n				    \r\n		     		\r\n		        {% endfor %} \r\n\r\n		         {% for itemobject in item.itemscat %}\r\n		         	{% set pricevalue = pricevalue + itemobject.qoutecat.catalogue.unitprice*itemobject.units %}\r\n		        	{{itemobject.qoutecat.catalogue.name}} X <b>{{itemobject.units}}	</b>\r\n		        	{% set totalcount = totalcount + itemobject.units %}\r\n	        		<br>\r\n				        \r\n				 {% endfor %}\r\n				        \r\n		     	\r\n\r\n			</td>\r\n			<td nowrap=\"nowrap\" style=\"text-align: right;\">R {{pricevalue|number_format(2, \'.\', \',\')}}</td>\r\n			<td>{% for itemobject in item.files_srn %}\r\n					<a href=\"{{itemobject.path}}\">Download</a>\r\n			      {% endfor %}\r\n			</td>\r\n	<td>{% for itemobject in item.qc_srn %}\r\n					<a href=\"{{itemobject.path}}\">Download</a>\r\n			      {% endfor %}\r\n			</td>\r\n			<td>{% for itemobject in item.files_delivery %}\r\n					<a href=\"{{itemobject.path}}\">Download</a>\r\n			      {% endfor %}\r\n			</td>\r\n			\r\n			<td>{% for itemobject in item.files_collection %}\r\n					<a href=\"{{itemobject.path}}\">Download</a>\r\n			      {% endfor %}\r\n			</td>\r\n			\r\n			<td>\r\n			    {% for itemobject in item.images_delivery %}\r\n					<a href=\"{{itemobject.path}}\"><img alt=\"Delivery\" title=\"Delivery\" class=\"media-object img-fluid rounded\" src=\"{{ itemobject.getThumb(80, \'auto\') }}\" /></a>\r\n			      {% endfor %}\r\n		\r\n			    {% for itemobject in item.images_collection %}\r\n			        <a href=\"{{itemobject.path}}\"><img alt=\"Collection\" title=\"Collection\" class=\"media-object img-fluid rounded\" src=\"{{ itemobject.getThumb(80, \'auto\') }}\" /></a>\r\n				\r\n			      {% endfor %}\r\n			</td>\r\n			\r\n			\r\n			{% set totalpricevalue = totalpricevalue + pricevalue %}\r\n			\r\n\r\n			\r\n		</tr>\r\n	{% endfor %} \r\n</tbody>\r\n<tfoot>\r\n	<tr>\r\n		<td colspan=\"7\"></td>\r\n		<td style=\"text-align: center;\" ><b>{{totalcount}}</b></td>\r\n		<td nowrap=\"nowrap\" style=\"text-align: right;\"><b>R {{totalpricevalue|number_format(2, \'.\', \',\')}}</b></td>\r\n		<td></td>\r\n		<td></td>\r\n		<td></td>\r\n		<td></td>\r\n	</tr>\r\n</tfoot>\r\n</table>\r\n</div>\r\n<br>\r\nKind regards,\r\n\r\nBT Industrial Team','',3,1,'2020-10-13 18:29:36','2024-08-16 11:07:29'),(30,'bt.notify.production.delay','Production Delay','Production delay to be sent to sales','Hi {{ to_name }},\r\n\r\n{{username}} has put a delay on production pipe {{items}} with quote {{quote}}. Here are the details below:\r\n\r\n**Client Name:** {{client}}. \r\n\r\n**Delay Reasons:** {{delayreason}}\r\n\r\n**Start Date:** {{start}}\r\n\r\n**Expected End Date** {{end}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2020-10-22 11:32:28','2020-11-09 14:57:37'),(31,'bt.notify.logistic.approval','Logistics Schedule Approval','Logistic approval notification.','Good Day {{ name }} ,\r\n\r\n{{username}} is  booking a {{vehicle}} on the {{schedule}} which has to be approved by the Logistic manager.  See link for more details.: {{response_details}}.\r\n\r\nKind Regards,\r\n\r\n\r\nBT Industrial Team','',1,1,'2020-10-28 22:24:19','2022-08-18 12:20:21'),(32,'bt.sales.newquote.requestqc','Request QC','Send request from sales to QC','Hi {{ to_name }},\r\n\r\n{{sales_name}} is requesting for {{items}} with the following details:\r\n\r\n**Company Name:** {{company_name}}.\r\n\r\n**Quote Refence:** {{ref}}. \r\n\r\n**Pipe:** R{{quote_total}}\r\n\r\n**Message:** {{notes}}\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2020-11-03 12:28:40','2020-11-03 12:28:40'),(33,'bt.sales.reqcertificates.notify','Certificate Request From Sales','Notifying QC of pipe certificates request from sales','Good Day {{qc}}\r\n\r\n{{salesperson}} has requested {{certificate}} certificates for quote number: {{quote}}.\r\n\r\nKind Regards.\r\n\r\nBT Industrial Team','',1,1,'2020-11-04 22:50:30','2020-11-04 22:50:30'),(34,'bt.qc.notify.sales.Certificate','Request For  Compiling of Certificates','Compiling of Certificates','Hi {{ name }},\r\n\r\n{{username}} is requesting COC approval. Here are the Details below:\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2020-11-06 12:24:30','2022-06-13 08:36:29'),(35,'bt.notify.pnratingquotes','HDPE High Class PN Rating Quotes / Past 7 days','HDPE High Class PN Rating Quotes','Hi {{ name }},\r\n\r\nNotification Date and Time: {{ \"now\"|date(\"m/d/Y H:i\") }} \r\n\r\n\r\n<h1>HPDE Quote Items with alert for the past **7 days**</h1>\r\n\r\nPlease see more flags  [here](https://bailaerp.bt-industrial.co.za/backend/bt/sales/Quoteitems), Approval function to come. \r\n<div >\r\n<table  style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellpadding=\"4px\" border=\"1px\">\r\n<thead>\r\n	<tr>\r\n		<th nowrap=\"nowrap\">ITEM #</th>\r\n		<th nowrap=\"nowrap\">QUOTE #</th>\r\n		<th nowrap=\"nowrap\">Flag</th>\r\n		<th nowrap=\"nowrap\">Client</th>\r\n        <th nowrap=\"nowrap\">Sales Person</th>\r\n     \r\n		<th nowrap=\"nowrap\">PN Rating</th>\r\n	\r\n		<th nowrap=\"nowrap\">Length</th>\r\n		\r\n		<th nowrap=\"nowrap\">Qty</th>\r\n        <th nowrap=\"nowrap\">Premuim Price</th>\r\n        <th nowrap=\"nowrap\">Quoted Price</th>\r\n        <th nowrap=\"nowrap\">Margin Perc</th>\r\n        <th nowrap=\"nowrap\">Unit Price</th>\r\n        <th nowrap=\"nowrap\">Total Price</th>\r\n        <th nowrap=\"nowrap\">created_at</th>\r\n        \r\n        \r\n	</tr>\r\n</thead>\r\n<tbody>\r\n	\r\n    {% for item in tblitem %}\r\n       \r\n        \r\n			      \r\n		<tr>\r\n		    <td nowrap=\"nowrap\">{{item.id}}</td>\r\n		    <td nowrap=\"nowrap\">{{item.quote.id}}</td>\r\n		\r\n		    {% if item.flagit == 1%}\r\n		        <td nowrap=\"nowrap\" style=\"background-color: green; color: #ffffff\"> </td>\r\n		     {% elseif item.flagit == 0%}\r\n		        <td nowrap=\"nowrap\" style=\"background-color: blue; color: #ffffff\"> </td>\r\n		  {% elseif item.flagit == 3%}\r\n		        <td nowrap=\"nowrap\" style=\"background-color: orage; color: #ffffff\"> </td>\r\n		    {% else %}\r\n		        <td nowrap=\"nowrap\" style=\"background-color: red; color: #ffffff\">Warning</td>\r\n		    {% endif %}\r\n		    \r\n			<td nowrap=\"nowrap\">{{item.quote.company_name}}</td>\r\n			<td nowrap=\"nowrap\">{{item.quote.user.name}} {{item.quote.user.surname}}</td>\r\n			<td nowrap=\"nowrap\">{{item.product.PNRating.name}}</td>\r\n			\r\n			 <td nowrap=\"nowrap\">{{item.unitlength}}</td>\r\n			  <td nowrap=\"nowrap\">{{item.units}}</td>\r\n			  \r\n			  <td nowrap=\"nowrap\" style=\"text-align: right;\">R {{item.product.PNRating.premiumprice|number_format(2, \'.\', \',\')}}</td>\r\n			  \r\n			  <td nowrap=\"nowrap\" style=\"text-align: right;\">R {{item.priceperkg|number_format(2, \'.\', \',\')}}</td>\r\n			  \r\n			  <td nowrap=\"nowrap\">{{item.pricemargperc}}%</td>\r\n			  \r\n			  <td nowrap=\"nowrap\" style=\"text-align: right;\">R {{item.unitprice|number_format(2, \'.\', \',\')}}</td>\r\n			  \r\n			  <td nowrap=\"nowrap\" style=\"text-align: right;\">R {{item.price|number_format(2, \'.\', \',\')}}</td>\r\n			  \r\n			<td nowrap=\"nowrap\">{{item.created_at|date(\"m/d/Y\")}}</td>\r\n		\r\n			\r\n\r\n			\r\n		</tr>\r\n	{% endfor %} \r\n</tbody>\r\n\r\n</table>\r\n</div>\r\n<br>\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2021-04-12 14:09:14','2021-04-12 14:41:22'),(36,'bt.notify.approvals','BT HDPE: Latest Production and SRN Approvals','BT HDPE: Latest Production and SRN Approvals','Hi {{ name }},\r\n\r\nNotification Date and Time: {{ \"now\"|date(\"m/d/Y H:i\") }}\r\n\r\n<table  style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellpadding=\"4px\" border=\"1px\">\r\n	\r\n\r\n        <thead>\r\n        <tr>\r\n            <th><span>REF#</span></th>\r\n            <th><span>Project</span></th>\r\n            <th><span>Cost Affected</span></th>\r\n            <th><span>Date Approved</span></th>\r\n            <th><span>Date Updated</span></th>\r\n            <th><span>Approved By</span></th>\r\n            <th><span>Updated By</span></th>\r\n            <th><span>Approved</span></th>\r\n            <th><span>Note</span></th>\r\n        </tr>\r\n        </thead>\r\n        <tbody>\r\n            <tr><td colspan=\"9\" style=\"background: #2d3134;\"><h3 style=\"color: #ffffff ;font-size: 20px;padding: 0px; margin: 0px\">Production Approval / Last 20</h3></td></tr>\r\n\r\n            {% for item in batches %}\r\n\r\n      \r\n        <tr>\r\n            <td>{{item.id}}</td>\r\n            <td>{{item.quote.company_name}}</td>\r\n            <td style=\"text-align: right;\">R {{item.quote.totalincvat|number_format(2, \'.\', \',\')}}</td>\r\n            <td>{{item.approved.created_at|date(\"m/d/Y\")}}</td>\r\n            <td>{{item.approved.updated_at|date(\"m/d/Y\")}}</td>\r\n            \r\n            {% if item.approved.createdby.first_name %}\r\n                <td>{{item.approved.createdby.first_name}}  {{item.approved.createdby.last_name}}</td>\r\n            {% else %}\r\n                <td></td>\r\n            {% endif %}\r\n\r\n\r\n            {% if item.approved.updatedby.first_name %}\r\n                <td>{{item.approved.updatedby.first_name}} {{item.approved.updatedby.last_name}}</td>\r\n            {% else %}\r\n                <td></td>\r\n            {% endif %}\r\n\r\n            {% if item.approved.status_id %}\r\n                <td>Yes</td>\r\n            {% else %}\r\n                <td>No</td>\r\n            {% endif %}\r\n            <td>{{item.approved.note}}</td>\r\n\r\n        </tr>\r\n           {% endfor %}   \r\n\r\n        <tr><td colspan=\"9\" style=\"background: #2d3134;\"><h3 style=\"color: #ffffff ;font-size: 20px;padding: 0px; margin: 0px\">SRN Approval / Last 20</h3></td></tr>\r\n        \r\n        {% for item in srnapprov %}\r\n            {% set pricevalue = 0 %}\r\n            \r\n            {% for itemobject in item.items %}\r\n                {% set pricevalue = pricevalue + itemobject.pipe.quoteitems.price %}\r\n            {% endfor %} \r\n             \r\n            {% for itemobject in item.itemscat %}\r\n                {% set pricevalue = pricevalue + itemobject.qoutecat.catalogue.price %}\r\n            {% endfor %}        \r\n                    \r\n\r\n        <tr>\r\n            <td>{{item.id}}</td>\r\n            <td>{{item.quote.company_name}}</td>\r\n            <td style=\"text-align: right;\">R {{pricevalue|number_format(2, \'.\', \',\')}}</td>\r\n            <td>{{item.srnapprove.created_at|date(\"m/d/Y\")}}</td>\r\n            <td>{{item.srnapprove.updated_at|date(\"m/d/Y\")}}</td>\r\n            \r\n            {% if item.srnapprove.createdby.first_name %}\r\n                <td>{{item.srnapprove.createdby.first_name}} {{item.srnapprove.createdby.last_name}}</td>\r\n            {% else %}\r\n                <td></td>\r\n            {% endif %}\r\n\r\n\r\n            {% if item.srnapprove.updatedby.first_name %}\r\n                <td>{{item.srnapprove.updatedby.first_name}} {{item.srnapprove.updatedby.last_name}}</td>\r\n            {% else %}\r\n                <td></td>\r\n            {% endif %}\r\n\r\n            {% if item.srnapprove.status_id %}\r\n                <td>Yes</td>\r\n            {% else %}\r\n                <td>No</td>\r\n            {% endif %}\r\n            <td>{{item.srnapprove.note}}</td>\r\n\r\n        </tr>\r\n        {% endfor %}\r\n\r\n        </tbody>\r\n    </table>\r\n		\r\n		{% partial \'button\' url=\'https://bailaerp.bt-industrial.co.za/backend/bt/reporting/approvals/list\' type=\'positive\' body %}\r\nView Online\r\n{% endpartial %}\r\n\r\n		\r\n		<br>\r\nKind regards,\r\n\r\nBT Industrial Team','',3,1,'2021-07-12 17:53:56','2021-07-13 07:30:17'),(37,'bt.request.password','BT ERP Password Change','BT ERP Password Change','Hello {{ name }}\r\n\r\nYou are quested to change your password on the BT ERP System.\r\n\r\nYou can use the following link:\r\n\r\nhttps://bailaerp.bt-industrial.co.za/backend/backend/auth/restore\r\n\r\nYour **Login/User** name is: {{login}}\r\n\r\nKind regards,\r\nBT Industrial','',1,1,'2021-08-10 07:13:28','2021-08-10 07:13:28'),(38,'bt.notify.finance.approve','Request: Petty Cash Approval','Request: Petty Cash Approval','Hi {{ name }},\r\n\r\n{{username}} is requesting Petty Cash approval. Here are the Details below:\r\n\r\n{{MyMessage}}\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2022-02-11 06:21:21','2022-02-21 08:43:26'),(39,'bt.notify.pettycash.return','Petty Cash Response','bt.notify.pettycash.return','Hi {{ name }},\r\n\r\nHere is the Response of Petty Cash from {{username}}:\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2022-02-11 06:22:16','2022-02-11 06:22:16'),(40,'bt.notify.jobcard','bt.notify.jobcard','Job Card Request','Hi {{ name }},\r\n\r\n{{username}} is requesting Job Card approval. Here are the Details below:\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2022-03-09 08:54:14','2022-03-09 08:54:14'),(41,'bt.reponse.jobcard','bt.reponse.jobcard','Job Card Response','Hi {{ name }},\r\n\r\nHere is the Response of Job Card from {{username}}:\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2022-03-09 08:55:06','2022-03-09 08:55:06'),(42,'bt.jobcardnoti.notify','BT Daily Job Cards Notification','JobCards Notification','Hi {{ name }},\r\n\r\nNotification Date and Time: {{ \"now\"|date(\"m/d/Y H:i\") }} \r\n\r\n<h1> Latest 7 Days Job Cards </h1>\r\n<div >\r\n<table class=\"\" style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellspacing=\"0px\" cellpadding=\"2px\"  border=\"1\">\r\n<thead>\r\n	<tr>\r\n		<th nowrap=\"nowrap\">#</th>\r\n		<th nowrap=\"nowrap\">Open Date</th>\r\n		<th nowrap=\"nowrap\">Department</th>\r\n		<th nowrap=\"nowrap\">Assigned To</th>\r\n		<th nowrap=\"nowrap\">Summary</th>\r\n		<th nowrap=\"nowrap\">Budget</th>\r\n		<th nowrap=\"nowrap\">Status</th>\r\n		<th nowrap=\"nowrap\">Job Type</th>\r\n		<th nowrap=\"nowrap\">Priority Rate</th>\r\n		<th nowrap=\"nowrap\">Created By</th>\r\n    </tr>\r\n    </thead>\r\n	<tbody>\r\n		   \r\n		       {% for item in items %}\r\n										<tr>\r\n												<td nowrap=\"nowrap\">{{ item.id}}</td>\r\n											<td nowrap=\"nowrap\">{{item.opendate|date(\"Y/m/d\")}}</td>\r\n											<td nowrap=\"nowrap\">{{item.department.name}}</td>\r\n											<td nowrap=\"nowrap\">{{item.assignedto.name}}</td>\r\n											<td nowrap=\"nowrap\">{{item.job_summary}}</td>\r\n											<td nowrap=\"nowrap\">{{item.budget}}</td>\r\n											<td nowrap=\"nowrap\">\r\n												{%  if item.status.id == 1 %}\r\n													         <span style=\"color: yellow\">Scheduled</span>\r\n											   {% elseif  item.status.id == 2 %}\r\n												            <span style=\"color: orange\">In Progress</span>\r\n												{% elseif  item.status.id == 3 %}\r\n												         <span style=\"color: blue\">Postponed</span>\r\n												{% elseif  item.status.id == 4 %}\r\n												        <span style=\"color: red\">Cancelled</span>\r\n												{% elseif  item.status.id == 5 %}\r\n												          <span style=\"color: green\">Completed</span>\r\n												{% elseif  item.status.id == 6 %}\r\n												          <span style=\"color: indigo\">Requested</span>\r\n												{% else %}\r\n												          <span style=\"color: black\">In Discussion</span>\r\n													{% endif %}\r\n											</td>\r\n											<td nowrap=\"nowrap\">{{item.jobtype.name}}</td>\r\n											<td nowrap=\"nowrap\">\r\n													{% if item.priority == 1 %}\r\n														<span style=\"color: red\">Urgent</span>\r\n													{% else %}\r\n														 <span style=\"color: orange\">Not Urgent</span>\r\n													{% endif %}\r\n												</td>\r\n											   <td nowrap=\"nowrap\">{{item.createdby.first_name~\' \'~item.createdby.last_name}}</td>\r\n												<td nowrap=\"nowrap\"><a href=\"https://bailaerp.bt-industrial.co.za/backend/bt/maintenance/jobcard/update/{{item.id}}\">View JobCard </a></td>\r\n										</tr>\r\n          {% endfor %} \r\n		</tbody>\r\n</table>\r\n	    {% partial \'button\' url=\'https://bailaerp.bt-industrial.co.za/backend/bt/maintenance/jobcard/\' type=\'positive\' body %}\r\nView Online\r\n{% endpartial %}\r\n</div>\r\n<br>\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2022-04-26 10:22:40','2022-05-04 12:44:40'),(43,'BT.sales.pipe.pipeapproved','Pipe Association Approved','Approve','Hi {{to_name}}\r\n\r\n{{exec}} has approved the following pipe association:\r\n\r\nFrom Quote: {{from_quote}}\r\n\r\nTo Quote: {{to_quote}}\r\n\r\nPipe Item Associated: {{quote_item}}\r\n\r\nRegards\r\n\r\nThe BT Industrial Team','',1,1,'2022-05-30 10:40:49','2022-05-30 10:40:49'),(44,'BT.sales.pipe.piperequest','Requested Pipe Association','Get Request','Hi, {{to_name}}\r\n\r\nA request has been made by Sales to approve moving pipes from the followng:\r\n\r\nFrom Quote: {{from_quote.id}} > {{from_quote.company_name}}\r\n\r\nTo Quote: {{to_quote.id}} > {{to_quote.company_name}}\r\n\r\nQuantity Requested: {{quantity}}\r\n\r\nYou can find the entry through this link: {{response_details}}\r\n\r\nRegards\r\n\r\nThe BT Inudstrial Team','',1,1,'2022-05-30 10:45:37','2022-05-30 10:45:37'),(45,'bt.sales.pipemove.notify','Pipes Have Been Moved','PIpes Moved.','Hi {{salesperson}},\r\n\r\nThe following pipe in one of your quotes has been moved:\r\n\r\nFrom Quote:  #{{from_quote}} | {{from_client}}\r\n\r\nTo Quote: #{{to_quote}} | {{to_client}}\r\n\r\nItem:   {{pipe}}\r\n\r\nQuantity: {{quantity}}\r\n\r\nIn The Yard Now: {{yard}}\r\n\r\nRegards:\r\n\r\nThe BT Industrial Team','',1,1,'2022-07-22 07:06:06','2022-07-22 07:06:06'),(46,'BT.boardroom','Board Room Notifier','Email notification for boardroom schedules','Hi {{name}},\r\n\r\nBooking has been made for the booardroom by {{booker}} for <b>{{date}} at {{time}}</b>. Please see details below:\r\n\r\n\r\n<table class=\'table table-data\'>\r\n		<thead>\r\n			<tr>\r\n				<th colspan=\"3\" style=\'text-align: center\'>Meeting: {{meeting}}</th>\r\n			</tr>\r\n			<tr>\r\n				<th>Name</th>\r\n				<th>Surname</th>\r\n				<th>Department</th>\r\n			</tr>\r\n	</thead>\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n			{{attendname}}\r\n			</td>\r\n			<td>\r\n			{{attendsurname}}\r\n			</td>\r\n			<td>\r\n			{{department}}\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>','',1,1,'2023-02-19 16:54:49','2023-02-19 16:58:15'),(47,'bt.notify.booking','Boardroom Booking','Boardroom Booking','Hi {{ name }},\r\n\r\n{{username}} has made boardroom booking. Here are the Details below:\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2023-02-20 12:44:29','2023-02-20 12:44:29'),(48,'bt.notify.booking.return','Booking Response','Booking Response','Hi {{ name }},\r\n\r\nHere is the Response of Boardroom Booking from {{username}}:\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2023-02-22 09:17:15','2023-02-22 09:17:15'),(49,'bt.notify.operator.breakdown','Baila Breakdown','Baila Breakdown','Hi {{ name }},\r\n\r\n{{username}} is requesting Maintenance to fix baila breakdown. Here are the Details below:\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2023-03-29 13:02:38','2023-03-29 13:02:38'),(50,'BT.boardroom.invitation.send','Invitation to BT Industrial Group','This is to send invitation to visitors for BT Industrial Group','Hi {{name}}\r\n\r\nYou are being invited to BT Industrial Group! Your host will be {{host}}. To accept the invitation, please click <em>Go To Invitation</em> and accept when prompted. Looking forward to seeing you!\r\n<br>\r\n<br>\r\n<div class=\"text-center\">\r\n		<a style=\"font-size: 18px; text-align:center; text-decoration:none; color: whitesmoke; background: darkblue; display: block; border-radius: 10px;margin-left: auto; margin-right: auto;\r\n  width: 40%;\" href=\"{{url}}\"><b>Go To Invitation</b></a>\r\n	</div>\r\n	<br>\r\n<br>\r\n<p>Regards</p>\r\n\r\n<p>The BT Industrial Team</p>','',1,1,'2023-04-24 18:58:49','2023-04-25 09:06:56'),(51,'bt.notify.visit.return','Visit Induction Acceptance','Visit Induction Acceptance','Hi {{ name }},\r\n\r\n{{username}} signed and accepted induction :\r\n\r\n{{response_link}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2023-04-26 10:37:20','2023-08-01 09:09:57'),(52,'bt.notify.logistics','Logistics Schedule','Logistics Schedule','Hi {{ name }},\r\n\r\nNotification Date and Time: {{ \"now\"|date(\"m/d/Y H:i\") }} \r\n<div style=\"text-align:right;\">Delivery Type: D = Delivery From BT, C = Collection , O = Other</div>\r\n\r\n<h1>Logistics Schedule</h1>\r\n\r\n{% set today = \"now\"|date(\"Y-m-d\") %}\r\n{% set tomorrow = \"+1 day\"|date(\"Y-m-d\") %}\r\n{% set dayafter = \"+2 days\"|date(\"Y-m-d\") %}\r\n\r\n\r\n\r\n<div style=\"padding: 0px 1px\">\r\n    \r\n      <div class=\"col-sm-4\">\r\n      <h3 class=\"card-header \"style=\" margin-bottom: 0;\">Today<br>( {{today|date(\"D d M Y\")}} )</h3>\r\n      <div class=\"card-body\" style=\"flex-grow: 1; padding: 0px;\">\r\n        {% set count = 0 %}\r\n        {% set total_units = 0 %}\r\n                {% set total_weight = 0 %}\r\n        {% set show_table = false %}\r\n        <table  style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellpadding=\"4px\" border=\"1px\">\r\n          <thead>\r\n            <tr>\r\n              <th style=\"border: 1px solid #ccc; border-color: #ccc;\">Client</th>\r\n                            <th style=\"border: 1px solid #ccc; border-color: #ccc;\">Quote</th>\r\n                            <th style=\"border: 1px solid #ccc; border-color: #ccc;\">Sales Rep</th>\r\n                            <th style=\"border: 1px solid #ccc; border-color: #ccc;\">Qty</th>\r\n                            <th style=\"border: 1px solid #ccc; border-color: #ccc;\">Weight</th>\r\n                            <th style=\"border: 1px solid #ccc; border-color: #ccc;\">Type</th>\r\n            </tr>\r\n          </thead>\r\n          <tbody>\r\n            {% for itemobject in tbllogistics %}\r\n              {% if itemobject.schedule_date|date(\"Y-m-d\") == today %}\r\n                {% set show_table = true %}\r\n                {% set total_units = total_units + itemobject.items.sum(\'units\') + itemobject.itemscat.sum(\'units\') %}\r\n                        {% set tunits = itemobject.items.sum(\'units\') + itemobject.itemscat.sum(\'units\')  %}\r\n                <tr>               \r\n                  <td style=\"border: 1px solid #ccc; border-color: #ccc;\">{{itemobject.client.company_name}}</td>\r\n          <td style=\"border: 1px solid #ccc; border-color: #ccc;\">{{itemobject.quote.id}}</td>\r\n          <td style=\"border: 1px solid #ccc; border-color: #ccc;\">{{itemobject.createdby.first_name}} {{itemobject.createdby.last_name}}</td>\r\n          <td style=\"border: 1px solid #ccc; border-color: #ccc; text-align: center;\">\r\n            {{ tunits }}\r\n          </td>{% set item_weight = 0 %}\r\n                          {% for item in itemobject.items %}\r\n                              {% if item.quotecat is not  null %}\r\n                                  {% set weight = item.quotecat.weight  %}\r\n                                  {% set item_weight = item_weight + tunits * weight  %}\r\n                              {% endif %}\r\n                          {% endfor %}\r\n                          {% for itemcat in itemobject.itemscat %}\r\n                              {% if itemcat.quotecat is not  null %}\r\n                                  {% set weight = itemcat.quotecat.weight  %}\r\n                                  {% set item_weight = item_weight + tunits * weight  %}\r\n                              {% endif %}\r\n                          {% endfor %}\r\n                           <td style=\"border: 1px solid #ccc; border-color: #ccc; text-align: center;\">\r\n                              {{ item_weight|number_format(2, \'.\', \',\')  }} kg\r\n                          </td>\r\n          {% if itemobject.type.id == 1 %}\r\n                    <td style=\"border: 1px solid #ccc; border-color: #ccc; text-align: center;\">D</td>\r\n                  {% elseif itemobject.type.id == 2 %}\r\n                    <td style=\"border: 1px solid #ccc; border-color: #ccc; text-align: center;\">C</td>\r\n                  {% elseif itemobject.type.id == 3 %}\r\n                    <td style=\"border: 1px solid #ccc; border-color: #ccc; text-align: center;\">O</td>\r\n                  {% endif %}\r\n                </tr>\r\n						  {% set total_weight = total_weight + item_weight %}\r\n              {% endif %}\r\n            {% endfor %}\r\n          </tbody>\r\n          {% if show_table %}\r\n            <tfoot>\r\n              <tr>\r\n                 <td colspan=\"3\" style=\"border: 1px solid #ccc; border-color: #ccc;\"><b>Total:</b></td>\r\n        <td align=\"right\" style=\"border: 1px solid #ccc; border-color: #ccc;\">{{ total_units}} </td>\r\n                                <td align=\"right\" style=\"border: 1px solid #ccc; border-color: #ccc;\">{{ total_weight}} kg</td>\r\n              </tr>\r\n            </tfoot>\r\n          {% endif %}\r\n        </table>\r\n      </div>\r\n    </div>\r\n    <br><br>\r\n  <div class=\"col-sm-4\">\r\n      <h3 class=\"card-header\" style=\" margin-bottom: 0;\">Tomorrow<br>( {{tomorrow|date(\"D d M Y\")}} )</h3>\r\n      <div class=\"card-body\" style=\"flex-grow: 1; padding: 0px;\">\r\n        {% set count = 0 %}\r\n        {% set total_units = 0 %}\r\n                {% set total_weight = 0 %}\r\n        {% set show_table = false %}\r\n        <table style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellpadding=\"4px\" border=\"1px\" >\r\n          <thead>\r\n            <tr>\r\n              <th style=\"border: 1px solid #ccc; border-color: #ccc;\">Client</th>\r\n                            <th style=\"border: 1px solid #ccc; border-color: #ccc;\">Quote</th>\r\n                            <th style=\"border: 1px solid #ccc; border-color: #ccc;\">Sales Rep</th>\r\n                            <th style=\"border: 1px solid #ccc; border-color: #ccc;\">Qty</th>\r\n                            <th style=\"border: 1px solid #ccc; border-color: #ccc;\">Weight</th>\r\n                            <th style=\"border: 1px solid #ccc; border-color: #ccc;\">Type</th>\r\n\r\n            </tr>\r\n          </thead>\r\n          <tbody>\r\n            {% for itemobject in tbllogistics %}\r\n              {% if itemobject.schedule_date|date(\"Y-m-d\") == tomorrow %}\r\n                {% set show_table = true %}\r\n                {%