r\n  <tr>\r\n    <td><b>Pipe:</b></td><td>{{printpipe.controlsheets.jobcard.pipe.quoteitems.description}}</td>\r\n  </tr>\r\n\r\n  <tr>\r\n    <td><b>Client:</b></td><td> {{printpipe.controlsheets.jobcard.pipe.quoteitems.quote.company_name}}</td>\r\n  </tr>\r\n\r\n  <tr>\r\n    <td><b>Quote:</b></td><td>{{printpipe.controlsheets.jobcard.pipe.quoteitems.quote.id}}</td>\r\n  </tr>\r\n\r\n  <tr>\r\n    <td><b>Batch:</b></td><td>{{printpipe.controlsheets.jobcard_id}} - {{printpipe.controlsheets.batch_id}}</td>\r\n  </tr>\r\n\r\n  <tr>\r\n    <td><b>Bin:</b></td><td>{{printpipe.binarea.area}}</td>\r\n  </tr>\r\n  <tr>\r\n    <td><b>Weight:</b></td><td>{{printpipe.weight}} kg</td>\r\n  </tr>\r\n    <tr>\r\n    <td><b> QC Status:</b></td><td>{{printpipe.qcstatus.name}}</td>\r\n  </tr>\r\n    {% if printpipe.reason_id is not empty %}\r\n        <tr>\r\n            <td><b> QC Reason:</b></td><td>{{printpipe.reason.reason}}</td>\r\n        </tr>\r\n    {% endif %}\r\n<tr>\r\n</tr>\r\n</table>','',1,1,'2023-05-26 09:15:12','2023-05-26 09:15:12'),(54,'BT.it.tasks.notifyinvoice','Task status: {{job_task_status}}','Task status: {{job_task_status}}','Hi {{ job_task_responder_name }},\r\n\r\nTask status: {{job_task_status}}\r\n\r\nTask assigned to: {{job_assigned_to_name}}\r\n\r\nExpected date: {{job_expected_date}}','',1,1,'2023-09-13 10:33:43','2023-10-03 07:37:22'),(55,'BT.sales.stockorder.notify','Available Stock Notification','Available Stock Notification','Hi {{ to_name }},\r\n\r\n{{ to_email }}\r\n\r\nNotification Date and Time: {{ \"now\"|date(\"m/d/Y H:i\") }}','',1,1,'2023-10-20 06:25:32','2023-10-20 06:25:32'),(56,'bt.sales.quoteApprovalNotification','Quote has been approved','Quote has been approved','Quote has been approved','',1,1,'2023-11-07 13:30:06','2023-11-07 13:30:06'),(57,'BT.sales.concession.send','BT.sales.concession.send','Non-SABS Concession Form','<p>Hi {{name}},</p>\r\n\r\n<p>Hope this message finds you well. We kindly request your assistance in signing a concession form. To streamline the process, you can access and sign the form by clicking on the following link:</p>\r\n\r\n<div style=\"text-align: center; margin-top: 20px;\">\r\n    <a style=\"font-size: 18px; text-decoration: none; color: #ffffff; background-color: #0073e6; display: inline-block; padding: 10px 20px; border-radius: 8px; text-align: center;\" href=\"{{url}}\"><strong>Concession Form</strong></a>\r\n</div>\r\n\r\n<br>\r\n\r\n<p>Your prompt attention to this matter is appreciated. If you have any questions or encounter any issues, please feel free to reach out. Thank you for your cooperation.</p>\r\n\r\n<p>Regards,</p>\r\n<p>The BT Industrial Team</p>','',1,1,'2023-11-30 07:16:23','2023-12-05 08:11:45'),(58,'bt.notify.concession.return','bt.notify.concession.return','Non-SABS Concession Form','Hi {{ name }},\r\n\r\n{{username}} signed and accepted concession form :\r\n\r\n{{response_link}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2023-11-30 07:17:35','2023-11-30 07:17:35'),(59,'BT.finance.requisition.po.request','Request Purchase Order','Request Purchase Order','Hi {{ name }},\r\n\r\n{{username}} is requesting Finance to create purchase order. Here are the Details below:\r\n\r\n**Supplier Name:** {{suppliername}}.\r\n\r\n**Date:** {{po.exp_date}}\r\n\r\n**Amount Total:** R{{amount}}\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2023-11-30 07:21:44','2023-12-01 09:17:39'),(60,'BT.finance.requisition.po.response','PO Response','PO Response','Hi {{ name }},\r\n\r\nHere is the Purchase Order (PO) response from {{username}}:\r\n\r\n**PO Number:** {{ponumber}}.\r\n\r\n**Date Created:** {{date}}\r\n\r\n{{response_details}}\r\n\r\nKind regards,\r\n\r\nBT Industrial Team','',1,1,'2023-12-01 09:18:35','2023-12-01 09:18:44'),(61,'BT.sales.response.productionrequest','Quote Approval Request','Request of load approval','<p>Hi {{to_name}}</p>\r\n\r\n<p>{{sales_name}} is requesting approval for the following quote:</p>\r\n\r\n<p>Quote No: {{ref}}</p>\r\n\r\n<p>Quote Items:</p>\r\n\r\n<table  style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellpadding=\"4px\" border=\"1px\">\r\n    <thead>\r\n        <tr>\r\n            <th>Description</th>\r\n            <th>Quantity</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n		{% for item in quoteObj.items %}\r\n        <tr>\r\n            <td>{{item.description}}</td>\r\n					 <td>{{item.units}}</td>\r\n        </tr>\r\n		{% endfor %}\r\n		{% for item in quoteObj.itemscat %}\r\n        <tr>\r\n            <td>{{item.description}}</td>\r\n					 <td>{{item.units}}</td>\r\n        </tr>\r\n		{% endfor %}\r\n    </tbody>\r\n</table>\r\n\r\n<br>\r\n<p>Quote Load Items:</p>\r\n\r\n<table  style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellpadding=\"4px\" border=\"1px\">\r\n    <thead>\r\n        <tr>\r\n					<th>Destination</th>\r\n            <th>Vehicle Type</th>\r\n						<th>Load Weight (Kg)</th>\r\n					 <th>Trip Qty</th>\r\n						<th>Rate Per Transport</th>\r\n						<th>Unit Price (R)</th>\r\n						<th>Discount %</th>\r\n						<th>Comment</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n		{% for item in quoteObj.dispatch %}\r\n        <tr>\r\n            <td>{{item.destination.name}}</td>\r\n						<td>{{item.vehicle.name}}</td>\r\n					   <td>{{item.vihicle_load_weight}}</td>\r\n					<td>{{item.qty}}</td>\r\n					   <td>{{item.rate_per_transport|number_format(2)}}</td>\r\n						 <td>{{item.unit_price}}</td>\r\n							<td>{{item.discount}}</td>\r\n					<td>{{item.comment}}</td>\r\n        </tr>\r\n		{% endfor %}\r\n    </tbody>\r\n</table>\r\n\r\n<p>Please use the link bellow to approve:</p>\r\n<div class=text-center>\r\n<b><a href=\"{{link}}\">Click Here</a></b>\r\n	</div>\r\n\r\nRegards','',1,1,'2023-12-01 11:50:45','2024-04-11 09:32:17'),(62,'BT.inventory.rawmaterialreceiving.confirmed','Confirmation of Verified Total Weights for Received Materials','Confirmation of Verified Total Weights for Received Materials','<p>Hello {{ company }},</p>\r\n\r\n<p>We are pleased to inform you that the materials have been received and their total weights have been verified. Please see the details below.</p>\r\n\r\n<p><strong>Details:</strong></p>\r\n<p>Company: {{ company }}</p>\r\n<p>PO Number: {{ ponumber }}</p>\r\n<p>Date of Receipt: {{ date }}</p>\r\n\r\n<table  style=\"width: 100%;border-collapse:collapse; font-size: 10px; border: 1px solid #ccc; border-color: #ccc\" cellpadding=\"4px\" border=\"1px\">\r\n    <thead>\r\n        <tr>\r\n            <th style=\"text-align: left;\"><b>Bag No</b></th>\r\n            <th style=\"text-align: left;\"><b>Supplier Weight</b></th>\r\n            <th style=\"text-align: left;\"><b>Actual Weight</b></th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        {% for bag in bags %}\r\n        <tr>\r\n            <td style=\"text-align: left;\">{{ bag.bag_number }}</td>\r\n            <td style=\"text-align: left;\">{{ bag.weight }}</td>\r\n            <td style=\"text-align: left;\">{{ bag.actual_weight }}</td>\r\n        </tr>\r\n        {% endfor %}\r\n    </tbody>\r\n    <tfoot>\r\n        <tr>\r\n            <th style=\"text-align: left;\"><b>Total</b></th>\r\n            <th style=\"text-align: left;\"><b>{{ totalWeight }}</b></th>\r\n            <th style=\"text-align: left;\"><b>{{ totalActualWeight }}</b></th>\r\n        </tr>\r\n    </tfoot>\r\n</table>\r\n\r\n<p>Thank you,</p>\r\n<p>The BT Industrial Team</p>','',1,1,'2024-07-01 09:06:37','2024-07-01 09:06:37'),(63,'BT.inventory.rawmaterialreceiving.confirm','Acknowledgment of Received Goods and Awaiting Total Weight Verification','Acknowledgment of Received Goods and Awaiting Total Weight Verification','Dear {{company}},\r\n\r\nWe hope you are doing well.\r\n\r\nWe acknowledge the receipt of {{bags_palletes}} pallets, weighing a total of {{to_kg}} KG, as per our order {{ponumber}}. The delivery arrived on {{date}}, and we have inspected the contents.\r\n\r\nFollowing our standard procedure, we will verify the total weight of the received goods and will send you the confirmed total weight (in kg) soon for your records.\r\n\r\nThank you for your prompt delivery. We appreciate your ongoing support and cooperation.\r\n\r\nBest regards,\r\n\r\nThe BT Industrial Team','',1,1,'2024-07-01 09:07:14','2024-07-01 09:07:14'),(64,'BT.sales.response.excoapprove','SRN EXCO Approval','For EXCO to approve the truck.','Good day {{name}} ,\r\n\r\nSRN number {{id}} is in need of manual input approval. You can use the link bellow:\r\n\r\n{{response_details}}\r\n\r\nKind Regards,\r\n\r\nBT Industrial Team','',1,1,'2024-09-17 09:14:54','2024-09-17 09:14:54');
